1	import Phaser from 'phaser';
2	import { BaseAbility } from './BaseAbility';
3	import type { GameSceneAPI, SpecialPoopType } from './types';
4	import type PoolablePoopBase from '../objects/PoolablePoopBase';
5	import { ensureGlowDot } from '../utils/glowDot';
6	import { GUMI_PARAMS } from '../config/abilityParams';
7	
8	const HIT_R = 18;
9	
10	// 꼬리가 시작되는 Y 오프셋 (플레이어 중심 기준, 양수=아래=발 쪽)
11	const TAIL_ORIGIN_Y = 10;
12	const SWAY_AMP      = 0.28; // 흔들림 진폭 (radians)
13	
14	// 꼬리 체인: 세그먼트 수, 간격, 스케일 (지렁이 파동)
15	const NUM_SEGS   = 14;   // 꼬리 세그먼트 수 (14 × 5px = 70px)
16	const STEP_DIST  = 5;    // 세그먼트 간 거리 (px)
17	const PHASE_STEP = 0.35; // 세그먼트마다 위상 어긋남
18	// 타원형: base·tip 가늘고 5~6번째 가장 두꺼움
19	const SEG_SCALES = [0.10, 0.20, 0.30, 0.37, 0.41, 0.42, 0.41, 0.36, 0.30, 0.22, 0.15, 0.10, 0.06, 0.03];
20	
21	// 꼬리 depth (플레이어 depth 5보다 낮아야 몸통 뒤에 숨음)
22	const TAIL_DEPTH = 3;
23	
24	// 여우불 9색
25	const FOX_FIRE_COLORS = [
26	  0xff2200,  // 빨
27	  0xff7700,  // 주
28	  0xffee00,  // 노
29	  0x00cc44,  // 초
30	  0x0066ff,  // 파
31	  0x3300cc,  // 남
32	  0xaa00ff,  // 보
33	  0xffffff,  // 흰
34	  0xcccccc,  // 검(회색 대체)
35	];
36	
37	// 꼬리 등장 순서: 빨→보→주→남→노→파→초→흰→검
38	const TAIL_COLORS = [
39	  0xff2200,  // 1번째: 빨
40	  0xaa00ff,  // 2번째: 보
41	  0xff7700,  // 3번째: 주
42	  0x3300cc,  // 4번째: 남
43	  0xffee00,  // 5번째: 노
44	  0x0066ff,  // 6번째: 파
45	  0x00cc44,  // 7번째: 초
46	  0xffffff,  // 8번째: 흰
47	  0xcccccc,  // 9번째: 검
48	];
49	
50	// 꼬리 배치 각도: 생성 순서에 대응하는 시각적 위치
51	// 최종 시각 배치(왼→오): 흰(190°) 빨(210°) 주(230°) 노(250°) 초(270°) 파(290°) 남(310°) 보(330°) 검(350°)
52	const TAIL_ANGLE_ORDER = [210, 330, 230, 310, 250, 290, 270, 190, 350]
53	  .map(deg => deg * Math.PI / 180);
54	
55	interface FoxFire {
56	  img: Phaser.GameObjects.Image;
57	  core: Phaser.GameObjects.Graphics;
58	  x: number;
59	  y: number;
60	  baseVx: number;
61	  speedY: number;
62	  phase: number;
63	  freq: number;
64	  trailTimer: number;
65	  color: number;
66	}
67	
68	interface TailSegImg {
69	  img: Phaser.GameObjects.Image;
70	  baseScale: number;
71	}
72	
73	interface TailObj {
74	  segs: TailSegImg[];
75	  baseAngle: number;
76	  swayPhase: number;
77	  swayFreq: number;
78	  color: number;
79	}
80	
81	/**
82	 * 구미 (UR) — 꼬리 9개 무적(기본) / 여우불 금똥 변환(특수)
83	 * 수치: GUMI_PARAMS 참조
84	 */
85	export class GumiAbility extends BaseAbility {
86	  // ── 여우불 (특수 능력) ─────────────────────────────────────────────
87	  private lastGumiScore = 0;
88	  private foxFires: FoxFire[] = [];
89	
90	  // ── 꼬리 스택 (기본 효과) ─────────────────────────────────────────
91	  private tailCount = 0;
92	  private lastTailScore = 0;
93	  private invincibleActive = false;
94	  private invincibleElapsed = 0;
95	  private tails: TailObj[] = [];
96	
97	  // ── 꼬리별 누적 효과 ──────────────────────────────────────────────
98	  // index % 3 === 0 (1,4,7번): 특수 똥 수집 +5점
99	  // index % 3 === 1 (2,5,8번): 이동 속도 +5px/s (Player에 직접 적용)
100	  // index % 3 === 2 (3,6,9번): 일반 똥 소환 -1개 (영구)
101	  private specialBonus = 0;
102	  private speedBonus = 0;
103	  private spawnReduction = 0;
104	
105	  // ── 디버그 텍스트 (임시) ──────────────────────────────────────────
106	  private debugText: Phaser.GameObjects.Text | null = null;
107	
108	  // ── 플레이어 depth 설정 (꼬리가 몸통 뒤에 렌더링되도록) ──────────
109	  override onCreate(api: GameSceneAPI): void {
110	    // 씬 재시작 시 onDestroy가 호출되지 않으므로 stale 참조를 여기서 정리
111	    this.tails = [];
112	    this.tailCount = 0;
113	    this.specialBonus = 0;
114	    this.speedBonus = 0;
115	    this.spawnReduction = 0;
116	    this.debugText = null;
117	
118	    api.player.setDepth(5);
119	    this.debugText = api.scene.add.text(8, 60, '', {
120	      fontSize: '11px',
121	      color: '#ffffaa',
122	      stroke: '#000000',
123	      strokeThickness: 3,
124	      lineSpacing: 2,
125	    }).setDepth(500).setAlpha(0.85).setVisible(false);
126	    this._updateDebugText();
127	  }
128	
129	  private _updateDebugText(): void {
130	    if (!this.debugText) return;
131	    this.debugText.setText([
132	      `🦊 꼬리 ${this.tailCount}/${GUMI_PARAMS.maxTails}`,
133	      `특수+${this.specialBonus}pt  속도+${this.speedBonus}  소환-${this.spawnReduction}`,
134	    ]);
135	  }
136	
137	  // ── 꼬리 추가 ─────────────────────────────────────────────────────
138	  private _addTail(api: GameSceneAPI): void {
139	    const { scene, player } = api;
140	    ensureGlowDot(scene);
141	
142	    const i         = this.tailCount;
143	    const color     = TAIL_COLORS[i] ?? 0xffffff;
144	    const baseAngle = TAIL_ANGLE_ORDER[i] ?? (270 * Math.PI / 180);
145	    const originX   = player.x;
146	    const originY   = player.y + TAIL_ORIGIN_Y;
147	
148	    const segs: TailSegImg[] = [];
149	    for (let s = 0; s < NUM_SEGS; s++) {
150	      const img = scene.add.image(
151	        originX + Math.cos(baseAngle) * (STEP_DIST * (s + 1)),
152	        originY + Math.sin(baseAngle) * (STEP_DIST * (s + 1)),
153	        'glow_dot',
154	      )
155	        .setDepth(TAIL_DEPTH)
156	        .setBlendMode(Phaser.BlendModes.ADD)
157	        .setTint(color)
158	        .setScale(0)
159	        .setAlpha(0.92);
160	      segs.push({ img, baseScale: SEG_SCALES[s] ?? 0.08 });
161	    }
162	
163	    // 등장 애니메이션 (base → tip 순차)
164	    segs.forEach((si, idx) => {
165	      scene.tweens.add({
166	        targets: si.img,
167	        scale: si.baseScale,
168	        delay: idx * 40,
169	        duration: 300,
170	        ease: 'Back.easeOut',
171	      });
172	    });
173	
174	    this.tails.push({
175	      segs,
176	      baseAngle,
177	      swayPhase: Phaser.Math.FloatBetween(0, Math.PI * 2),
178	      swayFreq:  Phaser.Math.FloatBetween(1.4, 2.8),
179	      color,
180	    });
181	
182	    if (i % 3 === 0) {
183	      this.specialBonus += GUMI_PARAMS.tailSpecialBonus;
184	    } else if (i % 3 === 1) {
185	      this.speedBonus += GUMI_PARAMS.tailSpeedBonus;
186	      player.addPermanentSpeed(GUMI_PARAMS.tailSpeedBonus);
187	    } else {
188	      this.spawnReduction += GUMI_PARAMS.tailSpawnReduction;
189	    }
190	
191	    this.tailCount++;
192	    this._updateDebugText();
193	
194	    if (this.tailCount >= GUMI_PARAMS.maxTails) {
195	      this._triggerInvincibility(api);
196	    }
197	  }
198	
199	  // ── 꼬리 지렁이 파동 업데이트 (매 프레임) ────────────────────────
200	  private _updateTailPositions(api: GameSceneAPI): void {
201	    if (this.tails.length === 0) return;
202	    const { player, scene } = api;
203	    const time    = scene.time.now * 0.001;
204	    const originX = player.x;
205	    const originY = player.y + TAIL_ORIGIN_Y;
206	
207	    for (const tail of this.tails) {
208	      let px = originX;
209	      let py = originY;
210	
211	      for (let s = 0; s < tail.segs.length; s++) {
212	        const si = tail.segs[s];
213	        if (!si.img.active) continue;
214	
215	        // 뿌리는 진폭 0, 끝으로 갈수록 진폭 증가 (지렁이 파동)
216	        const amp   = SWAY_AMP * (s / (NUM_SEGS - 1));
217	        const sway  = Math.sin(time * tail.swayFreq + tail.swayPhase + s * PHASE_STEP) * amp;
218	        const angle = tail.baseAngle + sway;
219	
220	        px += Math.cos(angle) * STEP_DIST;
221	        py += Math.sin(angle) * STEP_DIST;
222	        si.img.setPosition(px, py);
223	      }
224	    }
225	  }
226	
227	  // ── 점수 마일스톤 ─────────────────────────────────────────────────
228	  override onScoreMilestone(score: number, api: GameSceneAPI): void {
229	    // 여우불 (특수)
230	    if (score % GUMI_PARAMS.foxFireInterval === 0 && score > this.lastGumiScore) {
231	      this.lastGumiScore = score;
232	      this.summonFoxFires(api);
233	    }
234	    // 꼬리 추가 (기본) — 무적 중 누적 금지
235	    if (score % GUMI_PARAMS.tailInterval === 0 && score > this.lastTailScore && !this.invincibleActive) {
236	      this.lastTailScore = score;
237	      this._addTail(api);
238	    }
239	  }
240	
241	  // ── 무적 발동 ─────────────────────────────────────────────────────
242	  private _triggerInvincibility(api: GameSceneAPI): void {
243	    const { player, scene } = api;
244	    this.invincibleActive  = true;
245	    this.invincibleElapsed = 0;
246	
247	    // 꼬리 확대
248	    this.tails.forEach(t => {
249	      t.segs.forEach(si => {
250	        scene.tweens.add({
251	          targets: si.img,
252	          scale: si.baseScale * 1.5,
253	          duration: 320,
254	          ease: 'Back.easeOut',
255	        });
256	      });
257	    });
258	
259	    // 9색 버스트
260	    ensureGlowDot(scene);
261	    for (let i = 0; i < 9; i++) {
262	      const angle = (i / 9) * Math.PI * 2;
263	      const spark = scene.add.image(player.x, player.y, 'glow_dot')
264	        .setDepth(210)
265	        .setBlendMode(Phaser.BlendModes.ADD)
266	        .setTint(FOX_FIRE_COLORS[i])
267	        .setScale(0.6);
268	      scene.tweens.add({
269	        targets: spark,
270	        x: player.x + Math.cos(angle) * 65,
271	        y: player.y + Math.sin(angle) * 65,
272	        scale: 0, alpha: 0, duration: 520,
273	        ease: 'Quad.easeOut',
274	        onComplete: () => spark.destroy(),
275	      });
276	    }
277	  }
278	
279	  // ── 무적 카운트다운 ───────────────────────────────────────────────
280	  private _updateInvincibility(api: GameSceneAPI): void {
281	    this.invincibleElapsed += api.scene.game.loop.delta;
282	    if (this.invincibleElapsed >= GUMI_PARAMS.invincibleDuration) {
283	      this._endInvincibility(api);
284	    }
285	  }
286	
287	  // ── 무적 종료 ─────────────────────────────────────────────────────
288	  private _endInvincibility(api: GameSceneAPI): void {
289	    const { player, scene } = api;
290	
291	    this.invincibleActive = false;
292	    player.setAlpha(1);
293	
294	    // 꼬리 사라짐
295	    this.tails.forEach(t => {
296	      t.segs.forEach(si => {
297	        scene.tweens.add({
298	          targets: si.img, alpha: 0, scale: 0,
299	          duration: 380, ease: 'Quad.easeIn',
300	          onComplete: () => si.img.destroy(),
301	        });
302	      });
303	    });
304	    this.tails       = [];
305	    this.tailCount   = 0;
306	    this.lastTailScore = api.score; // 무적 중 지나친 마일스톤 역추적 방지
307	
308	    // 꼬리별 누적 효과 초기화 — speedBonus는 원복 후 초기화
309	    const speedToRemove = this.speedBonus;
310	    this.specialBonus   = 0;
311	    this.speedBonus     = 0;
312	    this.spawnReduction = 0;
313	    player.addPermanentSpeed(-speedToRemove);
314	    this._updateDebugText();
315	
316	    this._spawnBreakEffect(api);
317	    this._zapAllPoops(api);
318	  }
319	
320	  // ── 무적 종료 파열 이펙트 (센티넬 방어막 파열 스타일, 황금색) ────
321	  private _spawnBreakEffect(api: GameSceneAPI): void {
322	    const { player, scene } = api;
323	    const cx = player.x;
324	    const cy = player.y;
325	
326	    scene.cameras.main.flash(200, 255, 200, 50, true);
327	
328	    // 확산 링 2겹
329	    [{ delay: 0, maxScale: 4.3 }, { delay: 80, maxScale: 3.4 }].forEach(({ delay, maxScale }) => {
330	      const ring = scene.add.graphics().setDepth(150);
331	      ring.lineStyle(2.5, 0xffcc44, 0.9);
332	      ring.strokeEllipse(0, 0, 74, 98);
333	      ring.setPosition(cx, cy);
334	      scene.tweens.add({
335	        targets: ring, scaleX: maxScale, scaleY: maxScale, alpha: 0,
336	        duration: 500, delay, ease: 'Quad.easeOut',
337	        onComplete: () => ring.destroy(),
338	      });
339	    });
340	
341	    // 내부 섬광
342	    const fill = scene.add.graphics().setDepth(149);
343	    fill.fillStyle(0xffcc44, 0.25);
344	    fill.fillEllipse(0, 0, 74, 98);
345	    fill.setPosition(cx, cy);
346	    scene.tweens.add({
347	      targets: fill, alpha: 0, duration: 180, ease: 'Quad.easeOut',
348	      onComplete: () => fill.destroy(),
349	    });
350	
351	    // 황금 파편 8개
352	    for (let i = 0; i < 8; i++) {
353	      const angle = (i / 8) * Math.PI * 2 + Phaser.Math.FloatBetween(-0.25, 0.25);
354	      const speed = Phaser.Math.FloatBetween(40, 95);
355	      const w     = Phaser.Math.Between(5, 12);
356	      const h     = Phaser.Math.Between(2, 5);
357	      const shard = scene.add.graphics().setDepth(152);
358	      shard.fillStyle(0xffcc44, 1);
359	      shard.fillRect(-w / 2, -h / 2, w, h);
360	      shard.setPosition(cx, cy);
361	      shard.setRotation(angle);
362	      scene.tweens.add({
363	        targets: shard,
364	        x: cx + Math.cos(angle) * speed,
365	        y: cy + Math.sin(angle) * speed,
366	        alpha: 0, rotation: angle + Phaser.Math.FloatBetween(-1, 1),
367	        duration: Phaser.Math.Between(270, 440), ease: 'Quad.easeOut',
368	        onComplete: () => shard.destroy(),
369	      });
370	    }
371	  }
372	
373	  // ── 반경 내 똥 전부 제거 ──────────────────────────────────────────
374	  private _zapAllPoops(api: GameSceneAPI): void {
375	    const { player, poops, scene } = api;
376	    const r  = GUMI_PARAMS.zapRadius;
377	    const r2 = r * r;
378	
379	    (poops.getChildren() as Phaser.Physics.Arcade.Sprite[])
380	      .filter(p => p.active && (p.x - player.x) ** 2 + (p.y - player.y) ** 2 <= r2)
381	      .forEach(p => (p as unknown as PoolablePoopBase).recycle());
382	
383	    ensureGlowDot(scene);
384	
385	    // 황금 확산 링 2겹
386	    for (let i = 0; i < 2; i++) {
387	      const ring = scene.add.graphics().setDepth(212);
388	      ring.lineStyle(3 - i, 0xffcc44, 0.9 - i * 0.3);
389	      ring.strokeCircle(0, 0, 20);
390	      ring.setPosition(player.x, player.y);
391	      scene.tweens.add({
392	        targets: ring, scaleX: r / 20, scaleY: r / 20, alpha: 0,
393	        delay: i * 80, duration: 560, ease: 'Quad.easeOut',
394	        onComplete: () => ring.destroy(),
395	      });
396	    }
397	
398	    // 중앙 섬광
399	    const flash = scene.add.image(player.x, player.y, 'glow_dot')
400	      .setDepth(213)
401	      .setBlendMode(Phaser.BlendModes.ADD)
402	      .setTint(0xffee88)
403	      .setScale(1.8);
404	    scene.tweens.add({
405	      targets: flash, scale: 0, alpha: 0, duration: 460,
406	      ease: 'Quad.easeOut',
407	      onComplete: () => flash.destroy(),
408	    });
409	  }
410	
411	  // ── 특수 똥 수집 보너스 (1,4,7번 꼬리) ──────────────────────────
412	  override onCollectSpecial(_type: SpecialPoopType): number {
413	    return this.specialBonus;
414	  }
415	
416	  // ── 일반 똥 소환 감소 (3,6,9번 꼬리) — 영구 감소이므로 리셋 없음 ──
417	  override getSpawnCountReduction(): number {
418	    return this.spawnReduction;
419	  }
420	
421	  // ── 피격: 무적 중이면 게임오버 방지 ──────────────────────────────
422	  override onHitPoop(_api: GameSceneAPI): boolean {
423	    return this.invincibleActive;
424	  }
425	
426	  // ── 여우불 소환 ───────────────────────────────────────────────────
427	  private summonFoxFires(api: GameSceneAPI): void {
428	    const { scene, player } = api;
429	    const N = GUMI_PARAMS.foxFireCount;
430	    ensureGlowDot(scene);
431	
432	    for (let i = 0; i < N; i++) {
433	      const ringAngle = (i / N) * Math.PI * 2;
434	      const x = player.x + Math.cos(ringAngle) * 55;
435	      const y = player.y + Math.sin(ringAngle) * 55;
436	      const color = FOX_FIRE_COLORS[i];
437	
438	      const img = scene.add.image(x, y, 'glow_dot')
439	        .setDepth(200)
440	        .setBlendMode(Phaser.BlendModes.ADD)
441	        .setTint(color)
442	        .setScale(0.45);
443	
444	      const core = scene.add.graphics().setDepth(202);
445	      core.fillStyle(0xffffff, 1);
446	      core.fillCircle(0, 0, 5);
447	      core.fillStyle(color, 0.85);
448	      core.fillCircle(0, 0, 3.5);
449	      core.setPosition(x, y);
450	
451	      this.foxFires.push({
452	        img, core, x, y, color,
453	        baseVx:     Phaser.Math.FloatBetween(-3.5, 3.5),
454	        speedY:     Phaser.Math.FloatBetween(4.5, 7.5),
455	        phase:      Phaser.Math.FloatBetween(0, Math.PI * 2),
456	        freq:       Phaser.Math.FloatBetween(0.07, 0.17),
457	        trailTimer: 0,
458	      });
459	    }
460	  }
461	
462	  // ── 매 프레임 ─────────────────────────────────────────────────────
463	  override onUpdate(api: GameSceneAPI): void {
464	    this._updateTailPositions(api);
465	    if (this.invincibleActive) this._updateInvincibility(api);
466	
467	    if (this.foxFires.length === 0) return;
468	
469	    const { scene } = api;
470	    const activePoops = api.poops.getChildren().filter(
471	      p => (p as Phaser.Physics.Arcade.Sprite).active,
472	    ) as Phaser.Physics.Arcade.Sprite[];
473	
474	    const remaining: FoxFire[] = [];
475	
476	    for (const fire of this.foxFires) {
477	      fire.trailTimer++;
478	      fire.x += fire.baseVx + Math.sin(fire.phase + fire.trailTimer * fire.freq) * 6;
479	      fire.y -= fire.speedY;
480	      fire.img.setPosition(fire.x, fire.y);
481	      fire.core.setPosition(fire.x, fire.y);
482	
483	      if (fire.trailTimer % 3 === 0) {
484	        const trail = scene.add.image(fire.x, fire.y, 'glow_dot')
485	          .setDepth(199)
486	          .setBlendMode(Phaser.BlendModes.ADD)
487	          .setTint(fire.color)
488	          .setScale(0.22);
489	        scene.tweens.add({
490	          targets: trail, scale: 0, alpha: 0, duration: 200,
491	          ease: 'Quad.easeOut',
492	          onComplete: () => trail.destroy(),
493	        });
494	      }
495	
